/**
 * @summary List Meta message templates for a channel (WhatsApp only; empty for IG/FB)
 */
export const getListCampaignTemplatesUrl = (
  params: ListCampaignTemplatesParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/campaigns/templates?${stringifiedParams}`
    : `/api/campaigns/templates`;
};

