/**
 * @summary Hilos de correo para la bandeja de Correo
 */
export const getListEmailThreadsUrl = (params?: ListEmailThreadsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/email/threads?${stringifiedParams}`
    : `/api/email/threads`;
};

export const listEmailThreads = async (
  params?: ListEmailThreadsParams,
  options?: RequestInit,
): Promise<ListEmailThreads200> => {
  return customFetch<ListEmailThreads200>(getListEmailThreadsUrl(params), {
    ...options,
    method: "GET",
  });
};

