/**
 * @summary Lo que se propone al crear la etiqueta de una parada (dirección leída del pedido, paquete de siempre, etiqueta vigente)
 */
export const getGetUspsLabelDraftUrl = (params: GetUspsLabelDraftParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/usps/draft?${stringifiedParams}`
    : `/api/usps/draft`;
};

